CREATE DATABASE IF NOT EXISTS ciudadela
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

CREATE TABLE jugadores (
  id INT AUTO_INCREMENT PRIMARY KEY,
  alias VARCHAR(50) NOT NULL UNIQUE,
  puntos INT NOT NULL DEFAULT 0
);

CONSTRAINT fk_jugador
  FOREIGN KEY (jugador_id) REFERENCES jugadores(id)
  ON DELETE CASCADE ON UPDATE RESTRICT;

ALTER TABLE jugadores ADD COLUMN nivel INT NOT NULL DEFAULT 1;
ALTER TABLE jugadores MODIFY COLUMN alias VARCHAR(80) NOT NULL;
ALTER TABLE jugadores DROP COLUMN nivel;

INSERT INTO jugadores (alias, puntos)
VALUES ('Arturo', 100), ('Morgana', 150)
ON DUPLICATE KEY UPDATE puntos = VALUES(puntos);

DELETE FROM sesiones
WHERE expirada = 1
ORDER BY id ASC LIMIT 50;
